new = '''    def _split_graph(self, S, limit, deficits, order):
        """Flow network where participants cannot be transited.

        Sinks are capped by how much each participant still has to receive, so
        a reservation never wastes capacity on a node that is already served.
        """
        n = self.n
        parts = self.parts
        pset = self.pset
        inn = {}
        for i, w in enumerate(parts):
            inn[w] = n + i
        N = n + len(parts)
        sig = N
        tau = N + 1
        lim = N + 2
        g = FlowGraph(N + 3)
        items = list(self.cap.items())
        if order is not None:
            rnd = random.Random(order)
            rnd.shuffle(items)
        for (u, v), c in items:
            if c <= 0:
                continue
            b = v if v not in pset else inn[v]
            g.add_arc(u, b, c)
        Sset = set(S)
        for w in parts:
            if w in Sset:
                g.add_arc(sig, w, INF)
            else:
                d = deficits.get(w, 0)
                if d > 0:
                    g.add_arc(inn[w], tau, d)
        g.add_arc(lim, sig, limit)
        return g, lim, tau, inn

    def deficits(self):
        inflow = {}
        for (a, b), c in self.m.items():
            inflow[b] = inflow.get(b, 0) + c
        out = {}
        for w in self.parts:
            need = self.total - self.rdem[w]
            d = need - inflow.get(w, 0)
            out[w] = d if d > 0 else 0
        return out

    def push(self, S, limit, deficits, order=None):
        g, lim, tau, inn = self._split_graph(S, limit, deficits, order)
        val, flows = g.maxflow_with_arcs(lim, tau)
        if val <= 0:
            return 0
        fnet = {}
        for i, f in flows:
            u = g.to[i ^ 1]
            v = g.to[i]
            fnet[(u, v)] = fnet.get((u, v), 0) + f
        rev_inn = {v: k for k, v in inn.items()}
        adj = {}
        for (u, v), f in fnet.items():
            if f <= 0:
                continue
            if u == lim or v == tau or u == tau or v == lim or u == self.n + len(self.parts):
                continue
            adj.setdefault(u, []).append([v, f])
        Sset = set(S)
        walks = []
        counts = []
        for st in [w for w in self.parts if w in Sset]:
            while True:
                lst = adj.get(st)
                if not lst:
                    break
                has = False
                for e in lst:
                    if e[1] > 0:
                        has = True
                        break
                if not has:
                    break
                path = []
                cur = st
                seen = {st}
                bottleneck = None
                while True:
                    lst = adj.get(cur)
                    e = None
                    if lst:
                        for cand in lst:
                            if cand[1] > 0:
                                e = cand
                                break
                    if e is None:
                        break
                    if e[0] in seen and e[0] not in rev_inn:
                        # flow cycle: drop it
                        e[1] = 0
                        continue
                    path.append((cur, e[0]))
                    if bottleneck is None or e[1] < bottleneck:
                        bottleneck = e[1]
                    seen.add(e[0])
                    cur = e[0]
                    if cur in rev_inn:
                        break
                if not path or cur not in rev_inn or not bottleneck:
                    break
                amt = bottleneck
                for (a, b) in path:
                    for e in adj[a]:
                        if e[0] == b and e[1] > 0:
                            take = amt if amt < e[1] else e[1]
                            e[1] -= take
                            break
                phys = []
                for (a, b) in path:
                    pa = rev_inn[a] if a in rev_inn else a
                    pb = rev_inn[b] if b in rev_inn else b
                    phys.append((pa, pb))
                walks.append(phys)
                counts.append(amt)
        if not walks:
            return 0
        got = 0
        for w, c in zip(walks, counts):
            for (a, b) in w:
                self.cap[(a, b)] = self.cap.get((a, b), 0) - c
                if self.cap[(a, b)] < 0:
                    raise RuntimeError('over-reserved %r' % ((a, b),))
            got += c
        bypair = {}
        for w, c in zip(walks, counts):
            key = (w[0][0], w[-1][1])
            bypair.setdefault(key, []).append((w, c))
        for (a, b), lst in bypair.items():
            merged = {}
            order2 = []
            for w, c in lst:
                k = tuple(w)
                if k not in merged:
                    merged[k] = 0
                    order2.append(k)
                merged[k] += c
            self._add(a, b, [list(k) for k in order2], [merged[k] for k in order2])
        return got

    def run(self, max_rounds=6000, seed=0):
        parts = self.parts
        rdem = self.rdem
        total = self.total
        n = self.n
        order = None if seed == 0 else seed
        for _ in range(max_rounds):
            dfc = self.deficits()
            target = None
            best = 0
            for w, d in dfc.items():
                if d > best:
                    best = d
                    target = w
            if target is not None:
                S = [v for v in parts if v != target]
                delta = best
            else:
                S = deficient_cut(n, self.m, parts, rdem, total)
                if S is None:
                    return True
                S = [v for v in S if v in self.pset]
                if not S:
                    return False
                delta = self.cut_deficiency(S)
            if delta <= 0:
                return False
            got = self.push(S, delta, dfc, order)
            if got <= 0:
                return False
        return False


'''
